// src/geocoder.ts
var cities = cities_default;
function toRad(value) {
  return value * Math.PI / 180;
}
function findClosestCity(lat, lon) {
  let closest = null;
  let minDistance = Infinity;
  const R = 6371;
  for (const city of cities) {
    const dLat = toRad(city.lat - lat);
    const dLon = toRad(city.lon - lon);
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(toRad(lat)) * Math.cos(toRad(city.lat)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const d = R * c;
    if (d < minDistance) {
      minDistance = d;
      closest = city;
    }
  }
  if (closest) {
    return { name: closest.name, state: closest.state };
  }
  return { name: "Unknown City", state: "Unknown State" };
}

// src/locationService.ts
async function detectDeviceLocation() {
  const globalCapacitor = typeof window !== "undefined" ? window.Capacitor : void 0;
  if (globalCapacitor?.Plugins?.Geolocation) {
    try {
      const Geolocation = globalCapacitor.Plugins.Geolocation;
      const permStatus = await Geolocation.checkPermissions();
      if (permStatus.location === "denied" || permStatus.coarseLocation === "denied") {
        const requested = await Geolocation.requestPermissions();
        if (requested.location === "denied" && requested.coarseLocation === "denied") {
          throw new Error("PERMISSION_DENIED");
        }
      } else if (permStatus.location === "prompt" || permStatus.location === "prompt-with-rationale") {
        const requested = await Geolocation.requestPermissions();
        if (requested.location === "denied" && requested.coarseLocation === "denied") {
          throw new Error("PERMISSION_DENIED");
        }
      }
      const position = await Geolocation.getCurrentPosition({
        enableHighAccuracy: true,
        timeout: 1e4,
        maximumAge: 0
      });
      const lat = parseFloat(position.coords.latitude.toFixed(4));
      const lon = parseFloat(position.coords.longitude.toFixed(4));
      const matched = findClosestCity(lat, lon);
      return {
        latitude: lat,
        longitude: lon,
        city: matched.name,
        state: matched.state
      };
    } catch (err) {
      if (err?.message === "PERMISSION_DENIED" || err?.code === 1) {
        throw new Error("PERMISSION_DENIED");
      }
    }
  }
  return new Promise((resolve, reject) => {
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      reject(new Error("NOT_SUPPORTED"));
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const lat = parseFloat(pos.coords.latitude.toFixed(4));
        const lon = parseFloat(pos.coords.longitude.toFixed(4));
        const matched = findClosestCity(lat, lon);
        resolve({
          latitude: lat,
          longitude: lon,
          city: matched.name,
          state: matched.state
        });
      },
      (error) => {
        if (error.code === 1) {
          reject(new Error("PERMISSION_DENIED"));
        } else if (error.code === 3) {
          reject(new Error("TIMEOUT"));
        } else {
          reject(new Error("UNKNOWN_ERROR"));
        }
      },
      { enableHighAccuracy: false, timeout: 12e3, maximumAge: 3e5 }
    );
  });
}

